"use strict";
// Each maker keeps the array it hands out, so the program can ask the
// island what it sees of it afterwards.
let kept;
exports.makeList = () => (kept = [1, 2, 3]);
exports.pushKept = (x) => {
  kept.push(x);
};
exports.keptJoin = () => kept.join(",");
exports.same = (v) => v === kept;
exports.holder = () => ({ items: (kept = [1, 2, 3]), name: "h" });
exports.later = () => Promise.resolve((kept = [1, 2, 3]));
exports.names = () => (kept = ["a", "b"]);
exports.grid = () => (kept = [[1], [2]]);
exports.maybe = (present) => (present ? (kept = [1, 2, 3]) : undefined);
exports.total = (xs) => xs.reduce((sum, x) => sum + x, 0);
